public class FrozenHolderTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        try {
            java.util.List<String> src =
                    new java.util.ArrayList<>(java.util.Arrays.asList("a", "b"));
            FrozenHolder holder = new FrozenHolder(src);
            check("initial contents copied", "[a, b]", holder.getItems().toString());

            src.add("c");
            check("adding to the original later has no effect", "[a, b]",
                    holder.getItems().toString());
            src.set(0, "z");
            check("editing the original later has no effect", "[a, b]",
                    holder.getItems().toString());

            Object addOutcome;
            try {
                holder.getItems().add("x");
                addOutcome = "no exception";
            } catch (UnsupportedOperationException e) {
                addOutcome = "UnsupportedOperationException";
            }
            check("getItems().add throws", "UnsupportedOperationException", addOutcome);

            Object removeOutcome;
            try {
                holder.getItems().remove("a");
                removeOutcome = "no exception";
            } catch (UnsupportedOperationException e) {
                removeOutcome = "UnsupportedOperationException";
            }
            check("getItems().remove throws", "UnsupportedOperationException", removeOutcome);

            check("view still reads correctly after rejected edits", "[a, b]",
                    holder.getItems().toString());

            FrozenHolder empty = new FrozenHolder(new java.util.ArrayList<>());
            check("empty holder works", "[]", empty.getItems().toString());
        } catch (Exception e) {
            System.out.println("FAIL  unexpected exception -- " + e.getClass().getSimpleName());
            failures++;
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

